// GetLastError : @brief Retrieves the last recorded error, if any.
// @param _detail   Output pointer to a human-readable description string.
// @param _severity Output severity level of the error.
// @return The HRL_Error code. Returns HRL_NO_ERROR if no error occurred.
func GetLastError() (EError, string, ESeverity) {
	var _o0 *C.char
	var _o1 C.HRL_ESeverity
	_r := C.HRL_GetLastError(&_o0, &_o1)
	return EError(_r), goString(_o0), ESeverity(_o1)
}

// ErrorEnumToString : @brief Converts an HRL_Error enum value to its string representation.
// @param err The error code to convert.
// @return A null-terminated string literal (e.g. "HRL_INVALID_ID").
func ErrorEnumToString(err EError) string {
	_r := C.HRL_ErrorEnumToString(C.HRL_EError(err))
	return goString(_r)
}

// SeverityEnumToString : @brief Converts an HRL_Severity enum value to its string representation.
// @param sev The severity level to convert.
// @return A null-terminated string literal (e.g. "HRL_SEVERITY_FATAL").
func SeverityEnumToString(sev ESeverity) string {
	_r := C.HRL_SeverityEnumToString(C.HRL_ESeverity(sev))
	return goString(_r)
}

func RegisterErrorCallback(callback CErrorCallback) {
	var _c0 C.HRL_CErrorCallback
	if callback != nil {
		callbacks.Store("HRL_CErrorCallback", callback)
		_c0 = C.HRL_CErrorCallback(C.hrlGoHRL_CErrorCallback)
	} else {
		callbacks.Delete("HRL_CErrorCallback")
	}
	C.HRL_RegisterErrorCallback(_c0)
}

// CreateMeshSprite : @brief Creates a sprite mesh in the given scene.
// A sprite is a textured quad that always faces the camera.
// @param _sceneid ID of the target scene.
// @return HRL_id of the new sprite, or HRL_InvalidID on failure.
func CreateMeshSprite(sceneid ID) ID {
	_r := C.HRL_CreateMeshSprite(C.HRL_id(sceneid))
	return ID(_r)
}

// SetMeshPivotPoint : @brief Sets the pivot (origin) point of a mesh or sprite.
