func SetGizmoChangedCallback(gizmoid ID, callback CGizmoChanged) {
	var _c1 C.HRL_CGizmoChanged
	if callback != nil {
		callbacks.Store(callbackKey{"HRL_CGizmoChanged", uint64(gizmoid)}, callback)
		_c1 = C.HRL_CGizmoChanged(C.hrlGoHRL_CGizmoChanged)
	} else {
		callbacks.Delete(callbackKey{"HRL_CGizmoChanged", uint64(gizmoid)})
	}
	C.HRL_SetGizmoChangedCallback(C.HRL_id(gizmoid), _c1, nil)
}

